/**
 * Generate the Firestore role helpers from the role vocabulary.
 *
 * Only the helpers are generated, between markers — the `match` blocks stay the
 * project's own. Generating the whole file would mean every project that adds a
 * collection has to fight the generator, and a generator people work around
 * stops being run.
 *
 * The split puts the invariant in the right place: **which roles exist and
 * which reach `/hq`** is one fact shared with the claim writer, so it is
 * generated; **what each collection allows** is a per-project decision, so it
 * is not. `morpheus hq rules --check` fails when the generated block has
 * drifted from the vocabulary, which is the case that silently opens a door.
 */
export declare const BEGIN = "// morpheus:begin roles \u2014 generated by `morpheus hq rules`, do not edit";
export declare const END = "// morpheus:end roles";
/** The generated block, marker lines included. */
export declare function renderRoleHelpers(): string;
/** A complete starter file, for a project that has no rules yet. */
export declare function renderFirestoreRules(): string;
export interface RulesUpdate {
    content: string;
    /** False when the file already matched — nothing to write. */
    changed: boolean;
}
/**
 * Refresh the generated block inside existing rules.
 *
 * A file with no markers is left alone and reported, rather than having a block
 * injected at a guessed position. Rules are a security boundary, and writing
 * into one at a position nobody chose is how a `match` block ends up outside
 * the `service` scope it was meant to be inside.
 */
export declare function updateRoleHelpers(existing: string): RulesUpdate | null;
